"""Reviewed benign installed operation, matching the corresponding gate contract."""
from __future__ import annotations

import importlib
import importlib.metadata as md
import json
import pathlib
import re
import sys
import traceback


class InvalidObservation(Exception):
    pass


def normalized(value):
    return re.sub(r"[-_.]+", "-", value).lower()


def main():
    spec = json.loads(pathlib.Path(sys.argv[1]).read_text(encoding="utf-8"))
    profile = sys.argv[2]
    c = spec["contracts"][0]
    report = {"id": c["id"], "status": "PASS", "origins": [], "prerequisites": []}
    try:
        requirements = spec.get("profile_dependencies", {}).get(profile, [])
        for req in requirements:
            try:
                observed = md.version(req["distribution"])
            except md.PackageNotFoundError:
                observed = None
            report["prerequisites"].append({"distribution": req["distribution"], "expected_version": req["version"], "observed_version": observed, "satisfied": observed == req["version"]})
        if not all(r["satisfied"] for r in report["prerequisites"]):
            report.update(status="BLOCKED", reason="Exact prerequisite profile not established; operation not run")
        else:
            dist = md.distribution(c["distribution"])
            if normalized(dist.metadata["Name"]) != normalized(c["distribution"]) or dist.version != c["version"]:
                raise InvalidObservation("Selected installed distribution identity mismatch")
            owned = {pathlib.Path(dist.locate_file(f)).resolve() for f in dist.files or []}
            for module in c["modules"]:
                obj = importlib.import_module(module)
                path = pathlib.Path(obj.__file__).resolve()
                if path not in owned or not path.is_relative_to(pathlib.Path(sys.prefix).resolve()):
                    raise InvalidObservation(f"Unowned target module: {module}: {path}")
                report["origins"].append({"module": module, "origin": str(path), "distribution": dist.metadata["Name"], "version": dist.version})
            if c["kind"] == "call":
                module, name = c["target"].split(":", 1)
                fn = getattr(importlib.import_module(module), name)
                result = fn(*c.get("args", []), **c.get("kwargs", {}))
                assert result == c["equals"], (result, c["equals"])
                report["value"] = result
            else:
                assert c["kind"] == "import"
    except InvalidObservation as e:
        report.update(status="INVALID", exception=type(e).__name__, message=str(e), traceback=traceback.format_exc())
    except Exception as e:
        report.update(status="FAIL", exception=type(e).__name__, message=str(e), traceback=traceback.format_exc())
    print("PUBLISHER_ORDINARY=" + json.dumps(report, sort_keys=True))
    return {"PASS": 0, "FAIL": 1, "BLOCKED": 2, "INVALID": 2}[report["status"]]


if __name__ == "__main__":
    raise SystemExit(main())
